import{_ as a,a as r,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"新概念英语：经典版四册学习目录","description":"经典版四册、348 个课时，按册与学习单元阅读原创讲解、重点词汇、语法和复习练习。","frontmatter":{"title":"新概念英语：经典版四册学习目录","description":"经典版四册、348 个课时，按册与学习单元阅读原创讲解、重点词汇、语法和复习练习。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"经典版四册、348 个课时，按册与学习单元阅读原创讲解、重点词汇、语法和复习练习。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"第一册：英语初阶 · 本册介绍","link":"/life/english/new-concept/book-1/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"第一册：英语初阶 · 本册介绍","link":"/life/english/new-concept/book-1/overview"}},"headers":[],"relativePath":"life/english/new-concept/overview.md","filePath":"life/english/new-concept/overview.md"}'),l={name:"life/english/new-concept/overview.md"};function t(i,e,h,s,c,p){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="新概念英语-经典版四册学习目录" tabindex="-1">新概念英语：经典版四册学习目录 <a class="header-anchor" href="#新概念英语-经典版四册学习目录" aria-label="Permalink to &quot;新概念英语：经典版四册学习目录&quot;">​</a></h1><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p><h2 id="四册学习路线" tabindex="-1">四册学习路线 <a class="header-anchor" href="#四册学习路线" aria-label="Permalink to &quot;四册学习路线&quot;">​</a></h2><h3 id="第一册-英语初阶" tabindex="-1">第一册：英语初阶 <a class="header-anchor" href="#第一册-英语初阶" aria-label="Permalink to &quot;第一册：英语初阶&quot;">​</a></h3><p>First Things First · 144 课 · 6 个学习单元</p><p>适合英语初学者或希望系统重建基础的人。先熟悉字母和基本音标；不要求已掌握时态，但需能把简单单词读出并辨认主语与动作。</p><p><a href="/life/english/new-concept/book-1/overview">进入本册</a> · <a href="/life/english/new-concept/book-1/contents">查看全部课时</a></p><h3 id="第二册-实践与进步" tabindex="-1">第二册：实践与进步 <a class="header-anchor" href="#第二册-实践与进步" aria-label="Permalink to &quot;第二册：实践与进步&quot;">​</a></h3><p>Practice and Progress · 96 课 · 4 个学习单元</p><p>能辨认主语、谓语和宾语，掌握 be、have、do 的基本变化，能阅读第一册程度的短对话；若 do/does/did 与动词原形的搭配仍不稳定，先复习基础句型再学习本册。</p><p><a href="/life/english/new-concept/book-2/overview">进入本册</a> · <a href="/life/english/new-concept/book-2/contents">查看全部课时</a></p><h3 id="第三册-培养技能" tabindex="-1">第三册：培养技能 <a class="header-anchor" href="#第三册-培养技能" aria-label="Permalink to &quot;第三册：培养技能&quot;">​</a></h3><p>Developing Skills · 60 课 · 3 个学习单元</p><p>建议已熟悉基本时态、被动语态、常用从句与日常词汇，能独立阅读短篇叙事并写出连贯的六至八句段落。若完成时、主谓一致或不定式仍不稳定，可先复习第二册对应结构。</p><p><a href="/life/english/new-concept/book-3/overview">进入本册</a> · <a href="/life/english/new-concept/book-3/contents">查看全部课时</a></p><h3 id="第四册-流利英语" tabindex="-1">第四册：流利英语 <a class="header-anchor" href="#第四册-流利英语" aria-label="Permalink to &quot;第四册：流利英语&quot;">​</a></h3><p>Fluency in English · 48 课 · 6 个学习单元</p><p>能够理解第三册常见长句、非谓语和复合句；能用英语写出有主题句与支持细节的短段。遇到生词时能先利用上下文判断词性，再核查词义。</p><p><a href="/life/english/new-concept/book-4/overview">进入本册</a> · <a href="/life/english/new-concept/book-4/contents">查看全部课时</a></p><h2 id="怎样使用" tabindex="-1">怎样使用 <a class="header-anchor" href="#怎样使用" aria-label="Permalink to &quot;怎样使用&quot;">​</a></h2><ol><li>从本册介绍判断基础是否合适，再打开单元导读。</li><li>每课先明确目标，学习重点词和语法，再分析原创例句。</li><li>自己完成自测和读写任务，展开解析核对。听说练习可用自己的教材录音，也可请同伴朗读本页原创示范；本站不内置录音。</li><li>单元结束做复习，按错误回到课时；全册语法和单词页用于检索。</li></ol><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><p>第一册保留奇数课的情景学习与偶数课的句型训练，共 144 个独立页面。本站训练是原创补充，不冒充原书习题答案。</p><h2 id="目录核对来源" tabindex="-1">目录核对来源 <a class="header-anchor" href="#目录核对来源" aria-label="Permalink to &quot;目录核对来源&quot;">​</a></h2><h3 id="第一册-英语初阶-1" tabindex="-1">第一册：英语初阶 <a class="header-anchor" href="#第一册-英语初阶-1" aria-label="Permalink to &quot;第一册：英语初阶&quot;">​</a></h3><ul><li><a href="https://zy.21cnjy.com/8921710" target="_blank" rel="noopener noreferrer">第一册144课目录核对（21世纪教育网）</a></li><li><a href="https://eol.nju.edu.cn/courses/xinke1-xdf.html" target="_blank" rel="noopener noreferrer">第一册课程目录交叉核对</a></li><li><a href="https://www.fltrp.com/" target="_blank" rel="noopener noreferrer">外语教学与研究出版社：版本与配套资料入口</a></li></ul><h3 id="第二册-实践与进步-1" tabindex="-1">第二册：实践与进步 <a class="header-anchor" href="#第二册-实践与进步-1" aria-label="Permalink to &quot;第二册：实践与进步&quot;">​</a></h3><ul><li><a href="https://www.jiwake.com/post/34197" target="_blank" rel="noopener noreferrer">经典第二册目录事实核对：96课课名与顺序（仅作目录来源）</a></li><li><a href="https://changqing.org/details/1" target="_blank" rel="noopener noreferrer">第二册课程目录交叉核对（仅作课名来源）</a></li><li><a href="https://chinabook.co.kr/goods/view_contents?no=11329&amp;zoom=1" target="_blank" rel="noopener noreferrer">第二册目录及末段课名交叉核对（仅作目录来源）</a></li></ul><h3 id="第三册-培养技能-1" tabindex="-1">第三册：培养技能 <a class="header-anchor" href="#第三册-培养技能-1" aria-label="Permalink to &quot;第三册：培养技能&quot;">​</a></h3><ul><li><a href="https://www.newconceptenglish.com/index.php?id=nce-3" target="_blank" rel="noopener noreferrer">NewConceptEnglish.com 第三册目录（核对英文课名、顺序与中文主题）</a></li><li><a href="https://www.youzack.com/ListeningExercise/AlbumIndex/?id=102" target="_blank" rel="noopener noreferrer">Youzack 第三册目录（交叉核对60课排列）</a></li></ul><h3 id="第四册-流利英语-1" tabindex="-1">第四册：流利英语 <a class="header-anchor" href="#第四册-流利英语-1" aria-label="Permalink to &quot;第四册：流利英语&quot;">​</a></h3><ul><li><a href="https://www.cypressbooks.com/new-concept-english-vol-4-workbook-9787560027753.html" target="_blank" rel="noopener noreferrer">Cypress Books：新版第四册练习册48课目录（ISBN 9787560027753）</a></li><li><a href="https://www.cypressbooks.com/new-concept-english-vol-4-teacher-s-book-9787560018416.html" target="_blank" rel="noopener noreferrer">Cypress Books：第四册教师用书单元与目录信息</a></li><li><a href="https://www.cp.com.cn/book/7-100-03676-3_18.html" target="_blank" rel="noopener noreferrer">商务印书馆：第四册自学辅导手册目录交叉核对</a></li><li><a href="https://www.ncego.com/lessons/250" target="_blank" rel="noopener noreferrer">主题核对：第17课人为生态干预</a></li><li><a href="https://wenbo.tv/galileo-reborn/" target="_blank" rel="noopener noreferrer">主题核对：第32课伽利略的科学史形象</a></li><li><a href="https://bj.xdf.cn/xingainian/jiangjie/sice/kewen/201507155343.html" target="_blank" rel="noopener noreferrer">主题核对：第45课科学与社会</a></li><li><a href="https://www.tingroom.com/print_431.html" target="_blank" rel="noopener noreferrer">主题核对：第47课露营与度假动机</a></li><li><a href="https://wenbo.tv/trading-standards/" target="_blank" rel="noopener noreferrer">主题核对：第8课贸易标准与重复检测</a></li></ul>',32)])])}const k=a(l,[["render",t]]);export{d as __pageData,k as default};
